# ============================================================================\n# Project Nyra - Worker-3060 Setup (Alienware M15R7 - RTX 3060 12GB VRAM)\n# ============================================================================\nparam(\n    [string]$BootstrapPath = \"$PSScriptRoot\\..\\..\",\n    [switch]$SkipDockerInstall = $false\n)\n\n$ErrorActionPreference = \"Stop\"\n\nfunction Write-Log {\n    param([string]$Message, [string]$Level = \"INFO\")\n    $timestamp = Get-Date -Format \"yyyy-MM-dd HH:mm:ss\"\n    Write-Host \"[$timestamp] [$Level] $Message\" -ForegroundColor $(if($Level -eq \"ERROR\") { \"Red\" } elseif($Level -eq \"SUCCESS\") { \"Green\" } else { \"Cyan\" })\n}\n\nfunction Test-AdminPrivileges {\n    $isAdmin = ([Security.Principal.WindowsPrincipal][Security.Principal.WindowsIdentity]::GetCurrent()).IsInRole([Security.Principal.WindowsBuiltInRole]\"Administrator\")\n    if (-not $isAdmin) {\n        Write-Log \"This script requires Administrator privileges.\" \"ERROR\"\n        exit 1\n    }\n}\n\nfunction Install-Docker {\n    if ($SkipDockerInstall) { return }\n    Write-Log \"Installing Docker Desktop with NVIDIA runtime...\"\n    $dockerUrl = \"https://desktop.docker.com/win/stable/Docker%20Desktop%20Installer.exe\"\n    $installerPath = \"$env:TEMP\\DockerDesktopInstaller.exe\"\n    Invoke-WebRequest -Uri $dockerUrl -OutFile $installerPath -TimeoutSec 300\n    & $installerPath install --quiet --accept-license\n    Write-Log \"Docker installed - restart may be needed\" \"SUCCESS\"\n}\n\nfunction Verify-NVIDIASetup {\n    Write-Log \"Verifying NVIDIA GPU setup...\"\n    try {\n        $nvidiaInfo = & nvidia-smi --query-gpu=name,memory.total --format=csv,noheader\n        Write-Log \"GPU Found: $nvidiaInfo\" \"SUCCESS\"\n    }\n    catch {\n        Write-Log \"NVIDIA GPU drivers not detected. Please install NVIDIA drivers first.\" \"ERROR\"\n        exit 1\n    }\n}\n\nfunction Start-WorkerServices {\n    Write-Log \"Starting Worker-3060 services (Ollama + monitoring)...\"\n    $composePath = Join-Path $BootstrapPath \"docker-composes\\worker-rtx3060-complete.yml\"\n    if (!(Test-Path $composePath)) {\n        Write-Log \"Docker compose file not found: $composePath\" \"ERROR\"\n        exit 1\n    }\n    Push-Location (Split-Path $composePath)\n    docker-compose -f (Split-Path $composePath -Leaf) up -d\n    Pop-Location\n    Write-Log \"Waiting for services to initialize...\"\n    Start-Sleep -Seconds 15\n}\n\nfunction Configure-Models {\n    Write-Log \"Configuring Ollama models for RTX 3060 (12GB VRAM)...\"\n    Write-Log \"  Pulling qwen2.5:7b-q4... (this takes ~5-10 minutes)\"\n    & docker exec worker-3060-ollama ollama pull qwen2.5:7b-q4_K_M | Out-Null\n    Write-Log \"  Model ready\" \"SUCCESS\"\n}\n\nfunction Register-Worker {\n    Write-Log \"Registering worker with orchestrator...\"\n    $orchestratorIP = \"100.64.0.1\"\n    $workerID = \"worker-3060\"\n    $workerIP = \"100.64.0.11\"\n    \n    # Health check to orchestrator\n    try {\n        $health = Invoke-WebRequest -Uri \"http://$orchestratorIP:6100/api/worker/register\" -Method POST -Body @{\n            \"worker_id\" = $workerID\n            \"tailscale_ip\" = $workerIP\n            \"gpu_type\" = \"RTX3060\"\n            \"vram_gb\" = 12\n            \"inference_url\" = \"http://$($workerIP):11434\"\n        } | ConvertTo-Json -TimeoutSec 5 -ErrorAction SilentlyContinue\n        Write-Log \"Worker registered with orchestrator\" \"SUCCESS\"\n    }\n    catch {\n        Write-Log \"Could not register with orchestrator (may be offline): $_\" \"WARN\"\n    }\n}\n\nfunction Display-Summary {\n    Write-Log \"========================================\" \n    Write-Log \"Worker-3060 Setup Complete!\" \"SUCCESS\"\n    Write-Log \"========================================\"\n    Write-Log \"\\nServices:\"\n    Write-Log \"  Ollama:      http://localhost:11434 (inference server)\"\n    Write-Log \"  GPU Metrics: http://localhost:9400 (DCGM exporter)\"\n    Write-Log \"\\nNext Steps:\"\n    Write-Log \"  1. Wait for model download to complete\"\n    Write-Log \"  2. Test: curl http://localhost:11434/api/tags\"\n    Write-Log \"  3. Connect via Tailscale to access from orchestrator\"\n    Write-Log \"  4. Verify at: http://100.64.0.11:11434/api/tags\"\n    Write-Log \"========================================\"\n}\n\ntry {\n    Write-Log \"========================================\"\n    Write-Log \"Project Nyra - Worker-3060 Bootstrap\"\n    Write-Log \"========================================\"\n    Test-AdminPrivileges\n    Verify-NVIDIASetup\n    Install-Docker\n    Start-WorkerServices\n    Configure-Models\n    Register-Worker\n    Display-Summary\n    Write-Log \"Worker-3060 bootstrap completed!\" \"SUCCESS\"\n}\ncatch {\n    Write-Log \"Error: $_\" \"ERROR\"\n    exit 1\n}\n"